	{ uint32_t s = 0xEu; uint32_t res = (ctx->d[0] & 0xFFFFu) * (uint32_t)s; unsigned n = 0; for (int k = 0; k < 16; k++) n += (s >> k) & 1; ctx->d[0] = res; cc_set(ctx, CC_N | CC_Z | CC_V | CC_C, (res & 0x80000000u ? CC_N : 0) | (res ? 0 : CC_Z)); hle_insn(ctx, 4 + 38 + 2 * n); }  /* 0014D4 muluw #14,%d0 */
